# ==============================================================================
# 4. PROCEDURAL 64x64 TEXTURE PAINTER
# ==============================================================================

def generate_texture(name, entity_def, packed_uvs):
    """Generates a rich 64x64 pixel art PNG texture for the entity."""
    c_map = entity_def["colors"]
    theme_rgba = hex_rgba(entity_def["theme_color"])
    base_rgba = hex_rgba(c_map["base"])
    shadow_rgba = hex_rgba(c_map["shadow"])
    highlight_rgba = hex_rgba(c_map["highlight"])
    eye_rgba = hex_rgba(c_map.get("eye", "#facc15"))
    pupil_rgba = hex_rgba(c_map.get("eye_pupil", "#09090b"))

    pixels = [[theme_rgba for _ in range(64)] for _ in range(64)]

    # Paint each bone's cubes into their mapped UV regions
    for b in entity_def["bones"]:
        bname = b["name"]
        for idx, c in enumerate(b.get("cubes", [])):
            ckey = f"{bname}_{idx}"
            u, v = packed_uvs[ckey]
            dx, dy, dz = c["size"]

            faces = [
                ("top", u + dz, v, dx, dz, 1.15),
                ("bottom", u + dz + dx, v, dx, dz, 0.75),
                ("right", u, v + dz, dz, dy, 0.90),
                ("front", u + dz, v + dz, dx, dy, 1.05),
                ("left", u + dz + dx, v + dz, dz, dy, 0.90),
                ("back", u + 2 * dz + dx, v + dz, dz, dy, 0.80)
            ]

            # Choose specific color scheme per bone
            cube_base = base_rgba
            if "belly" in c_map and ("body" in bname or "snout" in bname or "torso" in bname):
                cube_base = blend_colors(base_rgba, hex_rgba(c_map["belly"]), 0.4)
            elif "flower" in bname or "crest" in bname:
                flower_hex = c_map.get("flower", c_map.get("crest", "#ef4444"))
                cube_base = hex_rgba(flower_hex)
            elif "halo" in bname:
                cube_base = hex_rgba(c_map.get("halo", c_map.get("crest", "#38bdf8")))
            elif "horn" in bname or "talons" in bname or "fangs" in bname:
                horn_hex = c_map.get("horns", c_map.get("talons", c_map.get("fangs", "#ca8a04")))
                cube_base = hex_rgba(horn_hex)
            elif "armor" in bname or "shoulder" in bname or "plate" in bname or "chassis" in bname:
                armor_hex = c_map.get("armor", c_map.get("silver", c_map.get("base", "#334155")))
                cube_base = hex_rgba(armor_hex)
            elif "cape" in bname or "robe" in bname:
                cape_hex = c_map.get("cape", c_map.get("base", "#b91c1c"))
                cube_base = hex_rgba(cape_hex)
            elif "wing" in bname:
                wing_hex = c_map.get("wings", c_map.get("highlight", c_map.get("crest", "#60a5fa")))
                cube_base = hex_rgba(wing_hex)
            elif "shell" in bname or "carapace" in bname:
                shell_hex = c_map.get("shell", c_map.get("base", "#57534e"))
                cube_base = hex_rgba(shell_hex)
            elif "tentacle" in bname:
                tent_hex = c_map.get("horns", c_map.get("base", "#7e22ce"))
                cube_base = hex_rgba(tent_hex)
            elif "crown" in bname and "leaf" in c_map:
                cube_base = hex_rgba(c_map["crown"])
            elif "mane" in bname:
                cube_base = hex_rgba(c_map["mane"])
            elif name == "ichthon" and ("fin" in bname or bname == "tail_2"):
                cube_base = hex_rgba(c_map.get("fins", c_map["base"]))
            elif name in ("hyena", "alpha_hyena") and bname == "head" and idx == 1:
                cube_base = hex_rgba(c_map.get("muzzle", c_map["base"]))
            elif name in ("hyena", "alpha_hyena") and bname.startswith("ear_"):
                cube_base = hex_rgba(c_map.get("ear_inner", c_map["base"]))

            for fname, fx, fy, fw, fh, lum in faces:
                for py in range(fy, fy + fh):
                    for px in range(fx, fx + fw):
                        if 0 <= px < 64 and 0 <= py < 64:
                            is_edge = (px == fx or px == fx + fw - 1 or py == fy or py == fy + fh - 1)
                            x, y = px - fx, py - fy
                            grain = ((x * 31 + y * 43 + x * y * 7) % 11 - 5) * 0.013
                            factor = lum * (0.9 if is_edge else 1.0) + grain
                            col = shade_color(cube_base, factor)

                            # Detailed procedural textures per creature
                            if name in ("wolf", "white_wolf", "alpha_wolf"):
                                if bname in ("body", "neck", "mane"):
                                    if fname == "top" or y <= 1 + (x * 3 % 4 == 0):
                                        col = blend_colors(col, shadow_rgba, 0.75)
                                    elif fname == "bottom" or y >= fh - 2:
                                        if "belly" in c_map:
                                            col = blend_colors(col, hex_rgba(c_map["belly"]), 0.72)
                                    elif (x * 11 + y * 7) % 19 < 7:
                                        col = blend_colors(col, highlight_rgba, 0.5)
                                elif bname.startswith("leg_") and y >= fh - 2:
                                    col = shade_color(shadow_rgba, lum)
                                elif bname == "tail" and (x < 2 or x >= fw - 2):
                                    col = shade_color(shadow_rgba, lum)
                                elif bname == "head" and idx == 1:
                                    nose_key = "nose" if (fname == "front" and y == 0) else "muzzle"
                                    if nose_key in c_map:
                                        col = shade_color(hex_rgba(c_map[nose_key]), lum)
                                elif bname == "head" and fname in ("left", "right") and y == 1 and x in (1, fw - 2):
                                    col = eye_rgba
                            elif name in ("cactoid", "flowering_cactoid"):
                                if (px - fx) % 2 == 0:
                                    col = shade_color(col, 0.88)
                                if "spines" in c_map and (px + py * 2) % 5 == 0:
                                    col = hex_rgba(c_map["spines"])
                            elif name in ("white_mousse", "ultros"):
                                if (px * 7 + py * 11) % 19 == 0:
                                    col = (255, 255, 255, 255)
                                elif "glaze" in c_map and (px * 3 + py * 5) % 11 == 0:
                                    col = hex_rgba(c_map["glaze"])
                            elif name in ("belias", "firemane"):
                                if (px * 3 + py * 7) % 7 == 0:
                                    col = hex_rgba(c_map.get("magma", c_map["highlight"]))
                            elif name == "mateus":
                                if is_edge and "silver" in c_map:
                                    col = hex_rgba(c_map["silver"])
                                elif (px + py) % 4 == 0 and "glyph" in c_map:
                                    col = hex_rgba(c_map["glyph"])
                            # The 12 Cross-Series Creatures:
                            elif name == "rubicante":
                                if bname in ("cape", "body"):
                                    if (px + py * 2) % 4 == 0:
                                        col = blend_colors(col, highlight_rgba, 0.6)
                                elif bname == "horns" and (py - fy) < 2:
                                    col = hex_rgba(c_map["crest"])
                            elif name == "golbez":
                                if is_edge and bname in ("body", "head", "shoulder_left", "shoulder_right"):
                                    col = hex_rgba(c_map["crest"])
                                elif (px * 7 + py * 13) % 11 == 0:
                                    col = highlight_rgba
                            elif name == "mindflayer":
                                if "tentacle" in bname or bname == "horns":
                                    if (py - fy) >= fh - 2:
                                        col = hex_rgba(c_map["crest"])
                                elif (px + py * 3) % 7 == 0:
                                    col = blend_colors(col, hex_rgba(c_map["crest"]), 0.45)
                            elif name == "iron_giant":
                                if (px * 5 + py * 7) % 11 == 0:
                                    col = highlight_rgba
                                elif is_edge:
                                    col = shadow_rgba
                            elif name == "ifrit_pyreburner":
                                if (px * 4 + py * 6) % 7 == 0:
                                    col = highlight_rgba
                                elif bname == "horns" and (py - fy) < 2:
                                    col = hex_rgba(c_map["crest"])
                            elif name == "adamantoise":
                                if bname == "body" and (py - fy) % 3 == 0:
                                    col = blend_colors(col, hex_rgba(c_map["crest"]), 0.5)
                                elif is_edge:
                                    col = shadow_rgba
                            elif name == "gil_turtle":
                                if bname == "body":
                                    if is_edge:
                                        col = hex_rgba(c_map["crest"])
                                    elif (px + py) % 4 == 0:
                                        col = highlight_rgba
                            elif name == "shinryu":
                                if (px + py) % 3 == 0:
                                    col = highlight_rgba
                                elif is_edge and "wing" in bname:
                                    col = hex_rgba(c_map["crest"])
                            elif name == "omega_mk":
                                if px == fx + 1 or py == fy + 1:
                                    col = highlight_rgba
                                elif is_edge:
                                    col = hex_rgba(c_map["crest"])
                            elif name == "ultros":
                                if "tentacle" in bname and (py - fy) % 2 == 0:
                                    col = shadow_rgba
                                elif bname == "head" and fname == "front" and y >= fh - 2:
                                    col = (255, 255, 255, 255)
                            elif name == "atb_weapon":
                                if (px * 3 + py * 5) % 7 == 0:
                                    col = highlight_rgba
                                elif "wing" in bname or "crest" in bname:
                                    col = blend_colors(col, hex_rgba(c_map["crest"]), 0.6)
                            elif name == "kefka_god":
                                if "wing" in bname:
                                    col = blend_colors(col, hex_rgba(c_map["crest"]), 0.7 if (px % 2 == 0) else 0.3)
                                elif bname == "halo":
                                    col = hex_rgba(c_map["crest"])

                            pixels[py][px] = col

            # Facial Features on the Head front face
            if bname == "head" and idx == 0:
                front_x = u + dz
                front_y = v + dz
                eye_w = max(1, dx // 4)
                eye_h = max(1, dy // 3)
                ey_pos = front_y + dy // 3

                # Left eye
                ex_l = front_x + max(0, dx // 6)
                for ey in range(ey_pos, min(64, ey_pos + eye_h)):
                    for ex in range(ex_l, min(64, ex_l + eye_w)):
                        pixels[ey][ex] = eye_rgba
                if 0 <= ex_l < 64 and 0 <= ey_pos < 64:
                    pixels[ey_pos][ex_l] = pupil_rgba

                # Right eye
                ex_r = front_x + dx - max(0, dx // 6) - eye_w
                for ey in range(ey_pos, min(64, ey_pos + eye_h)):
                    for ex in range(ex_r, min(64, ex_r + eye_w)):
                        pixels[ey][ex] = eye_rgba
                if 0 <= ex_r < 64 and 0 <= ey_pos < 64:
                    pixels[ey_pos][ex_r] = pupil_rgba

    return pixels

# ==============================================================================
# 5. GEOMETRY & ANIMATION BUILDERS
# ==============================================================================

def separate_coplanar_cube(cube, earlier_boxes):
    """Bias overlapping faces apart without changing the dimensions used by box UVs."""
    origin, size = cube["origin"], cube["size"]
    inflate = 0.0
    while True:
        lo = [coord - inflate for coord in origin]
        hi = [coord + length + inflate for coord, length in zip(origin, size)]
        overlaps = any(
            all(max(lo[side], other_lo[side]) < min(hi[side], other_hi[side])
                for side in range(3) if side != axis)
            and (abs(lo[axis] - other_lo[axis]) < 1.0e-6 or abs(hi[axis] - other_hi[axis]) < 1.0e-6)
            for other_lo, other_hi in earlier_boxes for axis in range(3)
        )
        if not overlaps:
            earlier_boxes.append((lo, hi))
            return inflate
        inflate = round(inflate + 0.04, 2)


def build_geometry_json(name, entity_def, packed_uvs):
    """Builds valid Bedrock/GeckoLib 1.12.0 geometry dict."""
    bones = []
    earlier_boxes = []
    for b in entity_def["bones"]:
        bname = b["name"]
        bone_dict = {
            "name": bname,
            "pivot": b["pivot"]
        }
        if "parent" in b:
            bone_dict["parent"] = b["parent"]
        if "rotation" in b:
            bone_dict["rotation"] = b["rotation"]

        raw_cubes = b.get("cubes", [])
        if raw_cubes:
            cubes_arr = []
            for idx, c in enumerate(raw_cubes):
                ckey = f"{bname}_{idx}"
                uv = list(packed_uvs[ckey])
                cube = {"origin": c["origin"], "size": c["size"], "uv": uv}
                inflate = separate_coplanar_cube(cube, earlier_boxes)
                if inflate:
                    cube["inflate"] = inflate
                cubes_arr.append(cube)
            bone_dict["cubes"] = cubes_arr

        bones.append(bone_dict)

    return {
        "format_version": "1.12.0",
        "minecraft:geometry": [
            {
                "description": {
                    "identifier": f"geometry.ivalice.{name}",
                    "texture_width": 64,
                    "texture_height": 64,
                    "visible_bounds_width": 3,
                    "visible_bounds_height": 3,
                    "visible_bounds_offset": [0, 1, 0]
                },
                "bones": bones
            }
        ]
    }

def build_animation_json(entity_def):
    """Builds valid GeckoLib 1.8.0 animation dict."""
    return {
        "format_version": "1.8.0",
        "animations": entity_def["animations"]
    }

# ==============================================================================
# 6. BIOME SPAWNS UPDATER (MINECRAFT 26.3 SCHEMA)
# ==============================================================================

BIOME_CREATURE_MAP = {
    "dalmasca_estersand": ["ivalice:wolf", "ivalice:cactoid", "ivalice:cockatrice"],
    "dalmasca_westersand": ["ivalice:wolf", "ivalice:cactoid", "ivalice:cockatrice"],
    "ogir_yensa_sandsea": ["ivalice:wolf", "ivalice:cactoid", "ivalice:cockatrice"],
    "giza_plains_dry": ["ivalice:giza_rabbit", "ivalice:hyena", "ivalice:wolf", "ivalice:cockatrice"],
    "ozmone_plain": ["ivalice:giza_rabbit", "ivalice:hyena", "ivalice:wolf", "ivalice:cockatrice"],
    "tchita_uplands": ["ivalice:giza_rabbit", "ivalice:hyena", "ivalice:wolf", "ivalice:cockatrice"],
    "salikawood": ["ivalice:giza_rabbit", "ivalice:hyena", "ivalice:wolf", "ivalice:cockatrice"],
    "giza_plains_rains": ["ivalice:ichthon", "ivalice:giza_rabbit", "ivalice:hyena"],
    "phon_coast": ["ivalice:ichthon", "ivalice:giza_rabbit", "ivalice:hyena"],
    "golmore_jungle": ["ivalice:hyena", "ivalice:cockatrice"],
    "mosphoran_highwaste": ["ivalice:hyena", "ivalice:cockatrice"],
    "cerobi_steppe": ["ivalice:hyena", "ivalice:cockatrice"],
    "paramina_rift": ["ivalice:wolf", "ivalice:ichthon"],
    "feywood": ["ivalice:wolf", "ivalice:ichthon"],
    "nabreus_deadlands": ["ivalice:wolf", "ivalice:ichthon"],
}

CREATURE_SPAWN_PARAMS = {
    "ivalice:wolf": {"weight": 14, "min": 2, "max": 4},
    "ivalice:cactoid": {"weight": 12, "min": 1, "max": 3},
    "ivalice:cockatrice": {"weight": 12, "min": 2, "max": 4},
    "ivalice:giza_rabbit": {"weight": 18, "min": 2, "max": 5},
    "ivalice:hyena": {"weight": 10, "min": 1, "max": 3},
    "ivalice:ichthon": {"weight": 14, "min": 2, "max": 4},
}

def update_biome_spawns():
    """Updates the 15 biome JSON files without UTF-8 BOM."""
    updated_count = 0
    pattern = os.path.join(BIOMES_DIR, "*.json")
    files = glob.glob(pattern)

    for fpath in files:
        bname = os.path.splitext(os.path.basename(fpath))[0]
        if bname not in BIOME_CREATURE_MAP:
            continue

        with open(fpath, "r", encoding="utf-8") as f:
            data = json.load(f)

        attrs = data.setdefault("attributes", {})
        mob_spawns = attrs.setdefault("minecraft:gameplay/natural_mob_spawns", {})
        arg = mob_spawns.setdefault("argument", {})
        spawns_by_cat = arg.setdefault("spawns_by_category", {})
        new_ivalice_spawns = {"creature": [], "monster": [], "ambient": [],
                              "water_creature": [], "water_ambient": [],
                              "underground_water_creature": [], "axolotls": []}
        for mob_id in BIOME_CREATURE_MAP[bname]:
            params = CREATURE_SPAWN_PARAMS.get(mob_id, {"weight": 10, "min": 1, "max": 3})
            if mob_id == "ivalice:ichthon":
                category = "water_creature"
            elif mob_id in ("ivalice:cactoid", "ivalice:giza_rabbit"):
                category = "creature"
            else:
                category = "monster"
            new_ivalice_spawns[category].append({
                "count": {
                    "type": "minecraft:uniform",
                    "max_inclusive": params["max"],
                    "min_inclusive": params["min"]
                },
                "type": mob_id,
                "weight": params["weight"]
            })

        spawns_by_cat.update(new_ivalice_spawns)

        with open(fpath, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.write("\n")

        updated_count += 1
        print(f"  [Biome] Updated {bname}.json with {len(BIOME_CREATURE_MAP[bname])} canonical creature spawns.")

    return updated_count

# ==============================================================================
# 7. MAIN EXECUTION PIPELINE
# ==============================================================================

def main():
    print("================================================================")
    print(" Projeto Ivalice - GeckoLib 3D Entity & Biome Spawn Generator")
    print("================================================================")

    # 1. Ensure all destination directories exist
    for d in (GEO_DIR_1, GEO_DIR_2, ANIM_DIR_1, ANIM_DIR_2, TEXTURES_DIR):
        os.makedirs(d, exist_ok=True)

    generated_entities = []

    for name, entity_def in ENTITIES_DATA.items():
        # 2. Align geometry and pack its UVs in 64x64
        for bone in entity_def["bones"]:
            for cube in bone.get("cubes", []):
                snap_cube_to_pixels(cube)
        packed_uvs = pack_model_cubes(entity_def["bones"])

        # 3. Build & Save Geometry JSON at both locations
        geo_dict = build_geometry_json(name, entity_def, packed_uvs)
        geo_path_1 = os.path.join(GEO_DIR_1, f"{name}.geo.json")
        geo_path_2 = os.path.join(GEO_DIR_2, f"{name}.geo.json")

        for gp in (geo_path_1, geo_path_2):
            with open(gp, "w", encoding="utf-8") as f:
                json.dump(geo_dict, f, indent=2, ensure_ascii=False)
                f.write("\n")

        # 4. Build & Save Animation JSON at both locations
        anim_dict = build_animation_json(entity_def)
        anim_path_1 = os.path.join(ANIM_DIR_1, f"{name}.animation.json")
        anim_path_2 = os.path.join(ANIM_DIR_2, f"{name}.animation.json")

        for ap in (anim_path_1, anim_path_2):
            with open(ap, "w", encoding="utf-8") as f:
                json.dump(anim_dict, f, indent=2, ensure_ascii=False)
                f.write("\n")

        # 5. Build & Save 64x64 RGBA Texture
        pixels = generate_texture(name, entity_def, packed_uvs)
        tex_path = os.path.join(TEXTURES_DIR, f"{name}.png")
        save_png_64x64(tex_path, pixels)

        generated_entities.append(name)
        print(f"  -> Generated {name}: geo, anim ({len(anim_dict['animations'])} anims), tex (64x64)")

    # 6. Update Biomes
    print("\nUpdating Biome JSON files...")
    biomes_updated = update_biome_spawns()

    print("\n================================================================")
    print(f" Successfully generated assets for all {len(generated_entities)} entities!")
    print(f" Successfully updated {biomes_updated} biome JSON files!")
    print("================================================================")

if __name__ == "__main__":
    main()
